def maskPII(S):
    if "@" in S:
        # It's an email address
        name, domain = S.split("@")
        name = name.lower()
        masked_name = name[0] + "*" * 5 + name[-1]
        return masked_name + "@" + domain.lower()
    else:
        # It's a phone number
        digits = [c for c in S if c.isdigit()]
        local_number = "***-***-" + ''.join(digits[-4:])
        if len(digits) == 10:
            return local_number
        else:
            country_code = "+" + "*" * (len(digits) - 10) + "-"
            return country_code + local_number
